{
  "action": "REVISE",
  "target_rule_id": "E05",
  "principle": {
    "instruction": "Resolve anatomy-versus-observation ambiguity by semantic role: use ANAT only when a term directly names or localizes a body structure, region, or space; treat anatomy-associated terms as observations when they instead denote a radiographic representation, assessed structural category or property, finding extent, or procedural state.",
    "applies_when": "A generic noun or modifier is associated with anatomy but may describe what is depicted, measured, characterized, or altered rather than directly identify anatomy.",
    "exceptions": [
      "A term remains ANAT when it independently identifies a concrete body structure, region, space, or anatomical locator."
    ],
    "priority": 5,
    "examples": [
      "An organ name is ANAT, while its radiographic silhouette or outline is an observation.",
      "In a low-volume lung description, lung is ANAT while volume is an observation.",
      "Image markings and generic structural-category wording are observations when they are the assessed radiographic subject.",
      "A directional term modifying the extent of an amputation or device state is an observation rather than an anatomical locator."
    ]
  },
  "rationale": "The errors arise from treating every anatomy-associated word as a body referent. The revision preserves ANAT for concrete anatomy while consistently classifying depicted appearances, assessed properties or categories, and finding-state modifiers as observations."
}

{
  "action": "REVISE",
  "target_rule_id": "E16",
  "principle": {
    "instruction": "Annotate a lexical predicate as an observation attribute when it directly asserts that a finding is recurrently demonstrated or visibly projects over, behind, or relative to another structure; assign it the certainty of the finding. Exclude only contextual function words that merely name a view, comparison frame, or relative reference without making such an assertion.",
    "applies_when": "A candidate term describes a finding as redemonstrated, projecting, overlying, or in a comparable image-based spatial or recurrence relationship.",
    "exceptions": [
      "Do not annotate view names, restriction words such as \"only,\" or comparison-introduction phrases unless they independently convey a clinically meaningful observation attribute."
    ],
    "priority": 16,
    "examples": [
      "Annotate \"redemonstration\" in a statement that a finding is again demonstrated.",
      "Annotate \"projecting\" when a lesion is described as projecting behind an anatomical structure.",
      "Annotate \"overlying\" when a nodule is described as overlying a rib, while labeling the rib reference as ANAT."
    ]
  },
  "rationale": "The current rule over-excludes image-based relational predicates as generic depiction. These predicates can directly characterize the asserted appearance or recurrence of a finding and are consistently labeled OBS-DP in the discrepancy evidence."
}

{
  "action": "REVISE",
  "target_rule_id": "E13",
  "principle": {
    "instruction": "Annotate a clinically meaningful degree, extent, temporal, morphological, distributional, acuity, measurement, or change descriptor only when it directly modifies an observation entity or itself functions as an asserted predicate. Do not create a standalone observation entity for a non-predicative adjective attached to an anatomical/reference noun phrase or to a generic depiction noun such as \"appearance\" or \"markings\".",
    "applies_when": "A candidate observation descriptor is grammatically attached to another entity or reference noun.",
    "exceptions": [
      "An anatomical locator remains ANAT regardless of the finding's certainty.",
      "Pure uncertainty cues and reporting verbs are not entities unless they independently denote the assessed observation."
    ],
    "priority": 13,
    "examples": [
      "Annotate \"mild\" in \"mild opacity\" because it directly modifies an observation.",
      "Annotate \"enlarged\" in \"the heart is enlarged\" because it is the asserted predicate.",
      "Exclude \"stable\" in \"stable appearance of a hernia\" while annotating the hernia.",
      "Exclude a standalone adjective in phrases such as \"calcified lymph nodes\" or \"crowded bronchovascular markings\" when it is non-predicatively attached to the anatomical or depictive noun phrase."
    ]
  },
  "rationale": "All three false positives are standalone adjectival spans attached to anatomy or generic depiction nouns rather than independent predicates or modifiers of explicit observation heads. This revision narrows the broad modifier rule while preserving descriptors that directly characterize findings or carry the asserted observation."
}

{
  "action": "REVISE",
  "target_rule_id": "E03",
  "principle": {
    "instruction": "Annotate semantically atomic units rather than maximal noun phrases, but keep a contiguous conventional multiword name for one anatomical structure or region as a single ANAT span.",
    "applies_when": "An anatomical modifier and anatomical head together form an established structural or regional name rather than a freely compositional localization.",
    "exceptions": [
      "Keep independently meaningful laterality, positional, level, and distribution qualifiers separate when they do not form a conventional anatomical name with the head.",
      "Keep a numeric measurement with its units and internal separators as one span.",
      "Do not include surrounding whitespace or ordinary terminal punctuation."
    ],
    "priority": 3,
    "examples": [
      "Annotate 'cervical spine' as one ANAT span because it names one conventional anatomical region.",
      "In 'left apical opacity', annotate the laterality and anatomical region separately from the observation head."
    ]
  },
  "rationale": "This revision prevents truncation of established modifier-head anatomical names while preserving atomic annotation for compositional locators. The punctuation-only boundary discrepancy does not justify reversing the general exclusion of ordinary terminal punctuation and is best treated as an isolated annotation inconsistency."
}

